{"code": "from hermes_tools import read_file

def read_file_chunked(path, offset_line, limit_lines):
    result = read_file(path=path, offset=offset_line, limit=limit_lines)
    if not result or not result.get('content'):
        return []
    lines = result['content'].splitlines(keepends=True)
    stripped_lines = []
    for line in lines:
        pipe_idx = line.find('|')
        if pipe_idx != -1:
            stripped_lines.append(line[pipe_idx+1:])
        else:
            stripped_lines.append(line)
    return stripped_lines

def is_heading(line):
    stripped = line.lstrip()
    return stripped.startswith('# ') or stripped.startswith('## ')

def heading_text(line):
    stripped = line.lstrip()
    if stripped.startswith('# '):
        return stripped[2:].strip()
    if stripped.startswith('## '):
        return stripped[3:].strip()
    return stripped

def main():
    path = "/home/bob/books/The_Unwritten_Future/THE_UNWRITTEN_FUTURE_FINAL.md"
    # Read first 10 lines to see what we get
    chunk = read_file_chunked(path, 1, 10)
    print("First 10 lines after stripping line numbers:")
    for i, line in enumerate(chunk):
        print(f"{i}: {repr(line)}")
    # Now count total lines by reading until empty
    total_lines = 0
    offset = 1
    while True:
        chunk = read_file_chunked(path, offset, 500)
        if not chunk:
            break
        total_lines += len(chunk)
        offset += 500
    print(f"Total lines: {total_lines}")
    # Collect headings
    headings = []
    offset = 1
    while offset <= total_lines:
        chunk = read_file_chunked(path, offset, 500)
        if not chunk:
            break
        for i, line in enumerate(chunk):
